INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 15, 'theory', 'Quiz: nested virtualization');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 15, 0, 'Why is nested virtualization hard if the processor has only one hypervisor mode?', '["There is only one hypervisor mode, so the L0 hypervisor emulates the virtualization extensions for L1", "The processor does not support multiple cores", "Guests cannot boot", "It requires two processors"]', 0, 'For the L1 guest, the illusion of real extensions is maintained entirely by the bottom hypervisor.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 15, 1, 'What is VMCS 0-2?', '["The description that L1 believes to be real", "The real structure with which L0 runs L2, built from the L0 and L1 descriptions", "The L2 page table", "The exit log"]', 1, 'This is the one L0 merges on every entry into L2; VMCS 1-2 is merely the description that L1 sees.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 15, 2, 'What does VMCS shadowing give you?', '["It encrypts the control structure", "It disables L2 exits", "L1 reads and writes permitted VMCS fields without an exit into L0, so the chain of exits is shorter", "It speeds up the disk"]', 2, 'Without it, every L1 access to a structure field is an exit into L0, and a single L2 exit spawns dozens.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 15, 3, 'How is the page table problem solved under nesting?', '["L2 uses the host tables directly", "Tables are no longer needed", "Only L1 shadow tables are used", "L0 merges L1''s EPT for L2 and its own EPT for L1 into a single table"]', 3, 'The hardware knows only one level of nested tables, so L0 builds a composition of the two.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 15, 4, 'How can you check from inside a guest that launching a second hypervisor is possible?', '["Run fsck", "Look for the vmx or svm flags in /proc/cpuinfo and the nested parameter of the KVM module", "Check the disk size", "Check the BIOS version"]', 1, 'If L1 has no virtualization flags, the second hypervisor can only run on software translation.');
